import { chromium } from 'playwright'

const base = 'http://localhost:8092/'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 1073 } })
const results = []
try {
  await page.goto(base, { waitUntil: 'networkidle' })
  // 打开经纪机构 -> 信用信息
  await page.locator('.menu-item').filter({ hasText: '经纪机构' }).getByText('信用信息', { exact: true }).click()
  await page.waitForTimeout(800)
  const h1 = await page.locator('.public-portal-header h1').innerText().catch(() => '(none)')
  results.push('title=' + h1)
  const codeCount = await page.locator('button.credit-code').count()
  results.push('credit-code buttons=' + codeCount)
  await page.screenshot({ path: 'verify-before-click.png' })
  // 点击第一个信用代码
  await page.locator('button.credit-code').first().click()
  await page.waitForTimeout(800)
  const dialogCount = await page.locator('.rental-detail-dialog').count()
  results.push('dialog count after click=' + dialogCount)
  if (dialogCount > 0) {
    const txt = await page.locator('.rental-detail-dialog').innerText()
    results.push('dialog has 厦门国贸=' + txt.includes('厦门国贸'))
  }
  await page.screenshot({ path: 'verify-after-click.png' })
} catch (e) {
  results.push('ERROR: ' + e.message)
} finally {
  await browser.close()
}
console.log(results.join('\n'))

import { chromium } from 'playwright'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 1073 } })
await page.goto('http://localhost:8092/', { waitUntil: 'networkidle' })
await page.locator('.menu-item').filter({ hasText: '经纪机构' }).getByText('信用信息', { exact: true }).click()
await page.waitForTimeout(600)
const codeColor = await page.locator('button.credit-code').first().evaluate(el => getComputedStyle(el).color)
const viewBtn = page.getByRole('button', { name: '查看', exact: true }).first()
const viewColor = await viewBtn.evaluate(el => getComputedStyle(el).color)
const codeFont = await page.locator('button.credit-code').first().evaluate(el => getComputedStyle(el).fontSize)
console.log('credit-code color:', codeColor)
console.log('查看 color:', viewColor)
console.log('credit-code fontSize:', codeFont)
await browser.close()
